import{_ as t,C as i,c as o,o as n,aa as s,G as a}from"./chunks/framework.Cn7WEiMX.js";const P=JSON.parse('{"title":"Terra API","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"terra-api","link":"/wiki/Terra/terra-api"}]},"headers":[],"relativePath":"wiki/Terra/terra-api/index.md","filePath":"wiki/Terra/terra-api/index.md"}'),p={name:"wiki/Terra/terra-api/index.md"};function _(c,e,d,T,u,m){const r=i("NolebaseGitContributors"),l=i("NolebaseGitChangelog");return n(),o("div",null,[e[0]||(e[0]=s('<h1 id="terra-api" tabindex="-1">Terra API <a class="header-anchor" href="#terra-api" aria-label="Permalink to &quot;Terra API&quot;">​</a></h1><p>Terra 实现了一个高级的通用世界生成 API，可以通过附属拓展配置结构。实际上，所有 Terra 的默认配置都通过拓展实现。</p><h2 id="附属" tabindex="-1">附属 <a class="header-anchor" href="#附属" aria-label="Permalink to &quot;附属&quot;">​</a></h2><p>附属即为 Terra 的拓展。对它本身来说，Terra 只是一个带有平台实现的 API，任何功能的实现都依赖于附属和配置。附属创建配置结构，而配置利用它们实现功能。</p><p>有些时候，一个附属可能会绕过配置实现某个功能，但我们仍然鼓励用户通过配置实现功能。</p><ul><li>Terra API 介绍 <ul><li>载入 Terra 附属</li><li>搭建开发环境</li><li>创建简单的附属</li><li>监听事件</li><li>添加结构</li><li>注册配置类型</li></ul></li><li>API 概念 <ul><li>验证附属</li><li>依赖注入</li><li>SLF4J 登入</li><li>事件</li><li>类型键</li><li>注册条目</li><li>构造</li><li>云注册命令</li></ul></li></ul>',6)),a(r),a(l)])}const k=t(p,[["render",_]]);export{P as __pageData,k as default};
